using FluentValidation;using OAS.Contracts.Sales.Enums;using OAS.Contracts.Sales.SalesInvoices;
namespace OAS.Application.Sales.SalesInvoices.Validation;
public sealed class CreateSalesInvoiceRequestValidator:AbstractValidator<CreateSalesInvoiceRequest>{public CreateSalesInvoiceRequestValidator(){RuleFor(x=>x.CustomerId).NotEmpty();RuleFor(x=>x.CurrencyId).NotEmpty();RuleFor(x=>x.InvoiceCode).MaximumLength(40);RuleFor(x=>x.Description).MaximumLength(1000);RuleFor(x=>x.Lines).NotEmpty();RuleForEach(x=>x.Lines).SetValidator(new SalesInvoiceLineRequestValidator());}}
public sealed class UpdateSalesInvoiceRequestValidator:AbstractValidator<UpdateSalesInvoiceRequest>{public UpdateSalesInvoiceRequestValidator(){RuleFor(x=>x.CustomerId).NotEmpty();RuleFor(x=>x.CurrencyId).NotEmpty();RuleFor(x=>x.RowVersion).NotEmpty();RuleFor(x=>x.Lines).NotEmpty();RuleForEach(x=>x.Lines).SetValidator(new SalesInvoiceLineRequestValidator());}}
public sealed class SalesInvoiceLineRequestValidator:AbstractValidator<SalesInvoiceLineRequest>{public SalesInvoiceLineRequestValidator(){RuleFor(x=>x.Quantity).GreaterThan(0);RuleFor(x=>x.ActualUnitPrice).GreaterThanOrEqualTo(0);RuleFor(x=>x.DiscountValue).GreaterThanOrEqualTo(0).When(x=>x.DiscountValue.HasValue);RuleFor(x=>x.TaxRate).GreaterThanOrEqualTo(0).When(x=>x.TaxRate.HasValue);RuleFor(x=>x.ProductVariantId).NotEmpty().When(x=>x.LineType is SalesLineType.Frame or SalesLineType.Lens or SalesLineType.Accessory);RuleFor(x=>x.WarehouseId).NotEmpty().When(x=>x.LineType is SalesLineType.Frame or SalesLineType.Lens or SalesLineType.Accessory);RuleFor(x=>x.Description).MaximumLength(500);RuleFor(x=>x.Notes).MaximumLength(1000);}}
